"""Aggregate the predeclared gates without discarding failed controls."""
from pathlib import Path
import hashlib,json,numpy as np
P=Path(__file__).resolve().parents[1];R=P/'receipts'
def read(n):return json.loads((R/n).read_text())
a=read('driven_cycle_064.json');b=read('driven_cycle_128.json');c=read('driven_cycle_128_q129.json')
