 ar=a['rows'];br=b['rows'][stride-1::stride];assert len(ar)==len(br)
 x=np.array([r['x_m'] for r in ar]);y=np.array([r['x_m'] for r in br]);fa=np.array([r['normal_wrenches'][2] for r in ar]);fb=np.array([r['normal_wrenches'][2] for r in br]);return dict(max_center_difference_m=float(max(abs(x-y))),center_relative_to_drive_amplitude=float(max(abs(x-y))/8e-6),normal_force_relative=float(np.linalg.norm(fa-fb)/np.linalg.norm(fb)),physical_heat_relative=abs(a['physical_friction_heat_J']/b['physical_friction_heat_J']-1),work_relative=abs(a['external_work_J']/b['external_work_J']-1))
