for x in [a,b,c]:
 x['maximum_force_residual_N']=max(abs(r['force_residual_N']) for r in x['rows']);x['minimum_one_sided_restoring_N_m']=min(min(r['one_sided_restoring_N_m']) for r in x['rows'])
record=dict(scope='Conditional symmetric two-sided rigid-span friction interface and driven cycle. No flexible spinning, wool calibration, multi-component loop contact or carpet appearance promotion.',checks=checks,passed=all(checks.values()),temporal_comparison=t,spatial_comparison=s,cycles=[{k:v for k,v in x.items() if k!='rows'} for x in [a,b,c]],preserved_failures=['exchange_tests.json: one-sided constitutive asymmetry','coupling_tests_coarse_difference_steps.json and symmetric_tests_switch_crossings.json: nonsmooth finite-difference switches','driven_cycle_016.json and driven_cycle_032.json: excess numerical work','driven_cycle_*_preparation_force_control.json: initial nominal preparation violates force gate; final current histories independently equilibrate it'],normal_energy_count=1,physical_fibres=2,rigid_stock_m=.0024,physical_radius_m=16e-6,total_cylinder_volume_m3=2*np.pi*(16e-6)**2*.0024,reference_line_stiffness_N_m2=2.5e9,friction_mu_benchmark=.3)
(R/'qualification.json').write_text(json.dumps(record,indent=2));files={str(p.relative_to(P)):dict(sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size) for p in P.rglob('*') if p.is_file() and p.suffix in ['.py','.json','.md','.npz','.log'] and '__pycache__' not in p.parts and p.name!='FREEZE.json'};(P/'FREEZE.json').write_text(json.dumps(files,indent=2,sort_keys=True));print(json.dumps(record,indent=2))
